CREATE TABLE "PartnerOrganization" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PartnerOrganization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PartnerClientCredential" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"clientId" TEXT NOT NULL,"partnerId" UUID NOT NULL,"environment" TEXT NOT NULL,"secretHash" TEXT NOT NULL,"scopes" TEXT[] NOT NULL,"expiresAt" TIMESTAMP(3),"revokedAt" TIMESTAMP(3),"rotatedFromId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PartnerClientCredential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PartnerEventReceipt" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"partnerId" UUID NOT NULL,"environment" TEXT NOT NULL,"eventId" TEXT NOT NULL,"payloadHash" TEXT NOT NULL,"eventType" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"requestId" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PartnerEventReceipt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PartnerWebhookSubscription" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"partnerId" UUID NOT NULL,"environment" TEXT NOT NULL,"endpointUrl" TEXT NOT NULL,"encryptedSecret" TEXT NOT NULL,"eventTypes" TEXT[] NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PartnerWebhookSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PartnerWebhookDelivery" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"partnerId" UUID NOT NULL,"subscriptionId" UUID NOT NULL,"environment" TEXT NOT NULL,"eventId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"body" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastStatusCode" INTEGER,"lastErrorCode" TEXT,"deliveredAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PartnerWebhookDelivery_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PartnerCampaignSubmission" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"partnerId" UUID NOT NULL,"environment" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"campaignId" UUID,"status" TEXT NOT NULL DEFAULT 'DRAFT',"payload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PartnerCampaignSubmission_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "PartnerClientCredential_clientId_key" ON "PartnerClientCredential"("clientId");
CREATE UNIQUE INDEX "PartnerEventReceipt_partnerId_environment_eventId_key" ON "PartnerEventReceipt"("partnerId","environment","eventId");
CREATE UNIQUE INDEX "PartnerWebhookDelivery_subscriptionId_environment_eventId_key" ON "PartnerWebhookDelivery"("subscriptionId","environment","eventId");
CREATE UNIQUE INDEX "PartnerCampaignSubmission_partnerId_environment_idempotencyKey_key" ON "PartnerCampaignSubmission"("partnerId","environment","idempotencyKey");
CREATE INDEX "PartnerOrganization_status_createdAt_idx" ON "PartnerOrganization"("status","createdAt");
CREATE INDEX "PartnerClientCredential_partnerId_environment_revokedAt_idx" ON "PartnerClientCredential"("partnerId","environment","revokedAt");
CREATE INDEX "PartnerEventReceipt_partnerId_environment_receivedAt_idx" ON "PartnerEventReceipt"("partnerId","environment","receivedAt");
CREATE INDEX "PartnerWebhookSubscription_partnerId_environment_active_idx" ON "PartnerWebhookSubscription"("partnerId","environment","active");
CREATE INDEX "PartnerWebhookDelivery_status_nextAttemptAt_idx" ON "PartnerWebhookDelivery"("status","nextAttemptAt");
CREATE INDEX "PartnerWebhookDelivery_partnerId_environment_createdAt_idx" ON "PartnerWebhookDelivery"("partnerId","environment","createdAt");
CREATE INDEX "PartnerCampaignSubmission_partnerId_environment_status_createdAt_idx" ON "PartnerCampaignSubmission"("partnerId","environment","status","createdAt");
ALTER TABLE "PartnerClientCredential" ADD CONSTRAINT "PartnerClientCredential_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "PartnerOrganization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PartnerEventReceipt" ADD CONSTRAINT "PartnerEventReceipt_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "PartnerOrganization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PartnerWebhookSubscription" ADD CONSTRAINT "PartnerWebhookSubscription_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "PartnerOrganization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PartnerWebhookDelivery" ADD CONSTRAINT "PartnerWebhookDelivery_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "PartnerOrganization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PartnerWebhookDelivery" ADD CONSTRAINT "PartnerWebhookDelivery_subscriptionId_fkey" FOREIGN KEY ("subscriptionId") REFERENCES "PartnerWebhookSubscription"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PartnerCampaignSubmission" ADD CONSTRAINT "PartnerCampaignSubmission_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "PartnerOrganization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
